package orderbook

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"math/big"
	"sync"
	"time"
)

type TenantID [32]byte
type OrderID [32]byte

type Order struct {
	ID        OrderID
	Tenant    TenantID
	Price     *big.Int
	Amount    *big.Int
	IsBuy     bool
	Timestamp int64
	Nonce     uint64
}

type CommitRevealOrder struct {
	CommitHash [32]byte
	CommitTime int64
	Revealed   bool
	Order      *Order
}

type OrderBook struct {
	mu            sync.RWMutex
	commitments   map[[32]byte]*CommitRevealOrder
	pendingOrders []*Order
	tenantNonces  map[TenantID]uint64
	revealWindow  int64
	matchDelay    int64
}

func NewOrderBook(revealWindow, matchDelay int64) *OrderBook {
	return &OrderBook{
		commitments:   make(map[[32]byte]*CommitRevealOrder),
		pendingOrders: make([]*Order, 0),
		tenantNonces:  make(map[TenantID]uint64),
		revealWindow:  revealWindow,
		matchDelay:    matchDelay,
	}
}

// appendLengthPrefixed appends a 4-byte big-endian length prefix followed by
// the field bytes, preventing hash ambiguity between variable-length fields.
func appendLengthPrefixed(dst, field []byte) []byte {
	var lenBuf [4]byte
	binary.BigEndian.PutUint32(lenBuf[:], uint32(len(field)))
	dst = append(dst, lenBuf[:]...)
	dst = append(dst, field...)
	return dst
}

func (ob *OrderBook) computeCommitHash(tenant TenantID, price, amount *big.Int, isBuy bool, nonce uint64) [32]byte {
	data := make([]byte, 0, 64)
	data = append(data, tenant[:]...)
	data = appendLengthPrefixed(data, price.Bytes())
	data = appendLengthPrefixed(data, amount.Bytes())
	if isBuy {
		data = append(data, 1)
	} else {
		data = append(data, 0)
	}
	var nonceBuf [8]byte
	binary.BigEndian.PutUint64(nonceBuf[:], nonce)
	data = append(data, nonceBuf[:]...)
	return sha256.Sum256(data)
}

func (ob *OrderBook) CommitOrder(tenant TenantID, commitHash [32]byte) error {
	ob.mu.Lock()
	defer ob.mu.Unlock()

	if _, exists := ob.commitments[commitHash]; exists {
		return ErrDuplicateCommit
	}

	ob.commitments[commitHash] = &CommitRevealOrder{
		CommitHash: commitHash,
		CommitTime: time.Now().UnixNano(),
		Revealed:   false,
	}
	return nil
}

func (ob *OrderBook) RevealOrder(tenant TenantID, price, amount *big.Int, isBuy bool, nonce uint64) error {
	ob.mu.Lock()
	defer ob.mu.Unlock()

	expectedHash := ob.computeCommitHash(tenant, price, amount, isBuy, nonce)

	commitment, exists := ob.commitments[expectedHash]
	if !exists {
		return ErrNoCommitment
	}

	if commitment.Revealed {
		return ErrAlreadyRevealed
	}

	now := time.Now().UnixNano()
	if now-commitment.CommitTime > ob.revealWindow {
		return ErrRevealExpired
	}

	if nonce <= ob.tenantNonces[tenant] {
		return ErrInvalidNonce
	}

	var nowBuf [8]byte
	binary.BigEndian.PutUint64(nowBuf[:], uint64(now))
	orderIDData := append(expectedHash[:], nowBuf[:]...)
	orderIDHash := sha256.Sum256(orderIDData)
	var orderID OrderID
	copy(orderID[:], orderIDHash[:])

	order := &Order{
		ID:        orderID,
		Tenant:    tenant,
		Price:     new(big.Int).Set(price),
		Amount:    new(big.Int).Set(amount),
		IsBuy:     isBuy,
		Timestamp: commitment.CommitTime,
		Nonce:     nonce,
	}

	commitment.Revealed = true
	commitment.Order = order
	ob.tenantNonces[tenant] = nonce
	ob.pendingOrders = append(ob.pendingOrders, order)

	return nil
}

func (ob *OrderBook) GetPendingOrders(requestingTenant TenantID) []*Order {
	ob.mu.RLock()
	defer ob.mu.RUnlock()

	result := make([]*Order, 0)
	now := time.Now().UnixNano()

	for _, order := range ob.pendingOrders {
		if order.Tenant == requestingTenant {
			result = append(result, order)
		} else if now-order.Timestamp > ob.matchDelay {
			result = append(result, order)
		}
	}
	return result
}

func (ob *OrderBook) GetCommitmentStatus(tenant TenantID, commitHash [32]byte) (bool, int64) {
	ob.mu.RLock()
	defer ob.mu.RUnlock()

	if c, exists := ob.commitments[commitHash]; exists {
		if c.Order != nil && c.Order.Tenant != tenant {
			return false, 0
		}
		return c.Revealed, c.CommitTime
	}
	return false, 0
}

func (ob *OrderBook) GetOrderBookDepth(requestingTenant TenantID) map[string]interface{} {
	ob.mu.RLock()
	defer ob.mu.RUnlock()

	now := time.Now().UnixNano()
	buyCount := 0
	sellCount := 0
	totalBuyVolume := new(big.Int)
	totalSellVolume := new(big.Int)

	for _, order := range ob.pendingOrders {
		if order.Tenant != requestingTenant && now-order.Timestamp <= ob.matchDelay {
			continue
		}
		if order.IsBuy {
			buyCount++
			totalBuyVolume.Add(totalBuyVolume, order.Amount)
		} else {
			sellCount++
			totalSellVolume.Add(totalSellVolume, order.Amount)
		}
	}

	return map[string]interface{}{
		"buy_count":         buyCount,
		"sell_count":        sellCount,
		"total_buy_volume":  totalBuyVolume.String(),
		"total_sell_volume": totalSellVolume.String(),
	}
}

func (ob *OrderBook) GetCommitmentCount() int {
	ob.mu.RLock()
	defer ob.mu.RUnlock()

	unrevealed := 0
	for _, c := range ob.commitments {
		if !c.Revealed {
			unrevealed++
		}
	}
	return unrevealed
}

var (
	ErrDuplicateCommit = &OrderBookError{"duplicate commitment"}
	ErrNoCommitment    = &OrderBookError{"no matching commitment found"}
	ErrAlreadyRevealed = &OrderBookError{"order already revealed"}
	ErrRevealExpired   = &OrderBookError{"reveal window expired"}
	ErrInvalidNonce    = &OrderBookError{"invalid nonce"}
)

type OrderBookError struct {
	msg string
}

func (e *OrderBookError) Error() string {
	return e.msg
}

func CommitHashHex(hash [32]byte) string {
	return hex.EncodeToString(hash[:])
}
